    22	    keysToPreserve.push(ONYXKEYS.NVP_PREFERRED_LOCALE);
    23	    keysToPreserve.push(ONYXKEYS.ACTIVE_CLIENTS);
    24	    keysToPreserve.push(ONYXKEYS.DEVICE_ID);
