    26	    // After signing out, set ourselves as offline if we were offline before logging out and we are not forcing it.
    27	    // If we are forcing offline, ignore it while signed out, otherwise it would require a refresh because there's no way to toggle the switch to go back online while signed out.
    28	    if (currentIsOffline && !currentShouldForceOffline) {
